cat > ScopedRule.java <<'EOF'
package hotel.messages;

import java.util.List;

/** A rule that only counts in the test mode, only outside it, or always. */
public final class ScopedRule implements MessageRule {

    public enum Scope {
        ALWAYS,
        TEST_MODE_ONLY,
        NORMAL_MODE_ONLY
    }

    private final MessageRule rule;
    private final boolean active;

    private ScopedRule(MessageRule rule, Scope scope, boolean testMode) {
        this.rule = rule;
        this.active = switch (scope) {
            case ALWAYS -> true;
            case TEST_MODE_ONLY -> testMode;
            case NORMAL_MODE_ONLY -> !testMode;
        };
    }

    public static MessageRule of(MessageRule rule, Scope scope, boolean testMode) {
        return new ScopedRule(rule, scope, testMode);
    }

    @Override
    public List<Draft> apply(Draft draft) {
        return active ? rule.apply(draft) : List.of(draft);
    }
}
EOF
cat > BlockInvalidAddress.java <<'EOF'
package hotel.messages;

import java.util.List;

/** Blocks the message when the address is not like name@site.com, so the front desk can call the guest. */
public final class BlockInvalidAddress implements MessageRule {

    @Override
    public List<Draft> apply(Draft draft) {
        return List.of(isValid(draft.to()) ? draft : draft.blocked());
    }

    static boolean isValid(String address) {
        if (address == null) {
            return false;
        }
        int at = address.indexOf('@');
        if (at < 1 || address.indexOf('@', at + 1) >= 0) {
            return false;
        }
        String domain = address.substring(at + 1);
        return domain.indexOf('.', 1) > 0 && domain.indexOf('.', 1) < domain.length() - 1
                || domain.lastIndexOf('.') > 0 && domain.lastIndexOf('.') < domain.length() - 1;
    }
}
EOF
